20	/// Builds the Linux project through the Makefile.
21	Future<void> buildLinux(
22	  LinuxProject linuxProject,
23	  BuildInfo buildInfo, {
24	    String target = 'lib/main.dart',
25	    SizeAnalyzer sizeAnalyzer,
26	  }) async {
27	  if (!linuxProject.cmakeFile.existsSync()) {
28	    throwToolExit('No Linux desktop project configured. See '
29	      'https://github.com/flutter/flutter/wiki/Desktop-shells#create '
30	      'to learn about adding Linux support to a project.');
31	  }
32	
33	  // Build the environment that needs to be set for the re-entrant flutter build
34	  // step.
35	  final Map<String, String> environmentConfig = buildInfo.toEnvironmentConfig();
36	  environmentConfig['FLUTTER_TARGET'] = target;
37	  if (globals.artifacts is LocalEngineArtifacts) {
38	    final LocalEngineArtifacts localEngineArtifacts = globals.artifacts as LocalEngineArtifacts;
39	    final String engineOutPath = localEngineArtifacts.engineOutPath;
40	    environmentConfig['FLUTTER_ENGINE'] = globals.fs.path.dirname(globals.fs.path.dirname(engineOutPath));
41	    environmentConfig['LOCAL_ENGINE'] = globals.fs.path.basename(engineOutPath);
42	  }
43	  writeGeneratedCmakeConfig(Cache.flutterRoot, linuxProject, environmentConfig);
44	
45	  createPluginSymlinks(linuxProject.parent);
46	
47	  final Status status = globals.logger.startProgress(
48	    'Building Linux application...',
49	    timeout: null,
50	  );
51	  try {
52	    final String buildModeName = getNameForBuildMode(buildInfo.mode ?? BuildMode.release);
53	    final Directory buildDirectory = globals.fs.directory(getLinuxBuildDirectory()).childDirectory(buildModeName);
54	    await _runCmake(buildModeName, linuxProject.cmakeFile.parent, buildDirectory);
55	    await _runBuild(buildDirectory);
56	  } finally {
57	    status.cancel();
58	  }
59	  if (buildInfo.codeSizeDirectory != null && sizeAnalyzer != null) {
60	    final String arch = getNameForTargetPlatform(TargetPlatform.linux_x64);
61	    final File codeSizeFile = globals.fs.directory(buildInfo.codeSizeDirectory)
62	      .childFile('snapshot.$arch.json');
63	    final File precompilerTrace = globals.fs.directory(buildInfo.codeSizeDirectory)
64	      .childFile('trace.$arch.json');
65	    final Map<String, Object> output = await sizeAnalyzer.analyzeAotSnapshot(
66	      aotSnapshot: codeSizeFile,
67	      // This analysis is only supported for release builds.
68	      outputDirectory: globals.fs.directory(
69	        globals.fs.path.join(getLinuxBuildDirectory(), 'release', 'bundle'),
70	      ),
71	      precompilerTrace: precompilerTrace,
72	      type: 'linux',
73	    );
74	    final File outputFile = globals.fsUtils.getUniqueFile(
75	      globals.fs.directory(getBuildDirectory()),'linux-code-size-analysis', 'json',
76	    )..writeAsStringSync(jsonEncode(output));
77	    // This message is used as a sentinel in analyze_apk_size_test.dart
78	    globals.printStatus(
79	      'A summary of your Linux bundle analysis can be found at: ${outputFile.path}',
80	    );
81	  }
82	}
