84	Future<void> _runCmake(String buildModeName, Directory sourceDir, Directory buildDir) async {
85	  final Stopwatch sw = Stopwatch()..start();
86	
87	  await buildDir.create(recursive: true);
88	
89	  final String buildFlag = toTitleCase(buildModeName);
90	  int result;
91	  try {
92	    result = await processUtils.stream(
93	      <String>[
94	        'cmake',
95	        '-G',
96	        'Ninja',
97	        '-DCMAKE_BUILD_TYPE=$buildFlag',
98	        sourceDir.path,
99	      ],
100	      workingDirectory: buildDir.path,
101	      environment: <String, String>{
102	        'CC': 'clang',
103	        'CXX': 'clang++'
104	      },
105	      trace: true,
106	    );
107	  } on ArgumentError {
108	    throwToolExit("cmake not found. Run 'flutter doctor' for more information.");
109	  }
110	  if (result != 0) {
111	    throwToolExit('Unable to generate build files');
112	  }
113	  globals.flutterUsage.sendTiming('build', 'cmake-linux', Duration(milliseconds: sw.elapsedMilliseconds));
114	}
