116	Future<void> _runBuild(Directory buildDir) async {
117	  final Stopwatch sw = Stopwatch()..start();
118	
119	  int result;
120	  try {
121	    result = await processUtils.stream(
122	      <String>[
123	        'ninja',
124	        '-C',
125	        buildDir.path,
126	        'install',
127	      ],
128	      environment: <String, String>{
129	        if (globals.logger.isVerbose)
130	          'VERBOSE_SCRIPT_LOGGING': 'true'
131	      },
132	      trace: true,
133	    );
134	  } on ArgumentError {
135	    throwToolExit("ninja not found. Run 'flutter doctor' for more information.");
136	  }
137	  if (result != 0) {
138	    throwToolExit('Build process failed');
139	  }
140	  globals.flutterUsage.sendTiming('build', 'linux-ninja', Duration(milliseconds: sw.elapsedMilliseconds));
